input.sparql:
SELECT ?sensor ?ts_id WHERE {
  ?zone brick:hasName "Core_top" .
  ?sensor brick:isPointOf ?zone .
  ?sensor rdf:type brick:ElectricPowerSensor .
  ?sensor ref:hasTimeseriesId ?ts_id .
}

SELECT ?point ?class WHERE {
  ?zone brick:hasName "Core_top" .
  ?point brick:isPointOf ?zone .
  OPTIONAL { ?point rdf:type ?class . }
}

SELECT ?point ?class ?ts_id WHERE {
  ?zone rdfs:label "Core_top" .
  { ?zone brick:hasPoint ?point } UNION { ?point brick:isPointOf ?zone } .
  OPTIONAL { ?point rdf:type ?class . }
  OPTIONAL { ?point ref:hasTimeseriesId ?ts_id . }
}
